contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address newOwner) public {
        require(newOwner != address(0), "newOwner must be nonzero");
        address oldOwner = c.owner();
        require(oldOwner == address(this), "test must be owner");

        bool reverted;
        try c.transferOwnership(newOwner) { reverted = false; } catch { reverted = true; }

        if (!reverted) {
            address afterOwner = c.owner();
            assert(afterOwner == newOwner);
        } else {
            address afterOwner = c.owner();
            assert(afterOwner == oldOwner);
        }
    }

    receive() external payable {}
}

